import pytest

import trudag.score as score
from trudag.dotstop.core.graph import LinkStatus, TrustableGraph
from trudag.dotstop.core.validator import Validator


def review_graph_elements(
    graph: TrustableGraph, items: list[str], links: list[tuple[str, str]]
):
    for item in items:
        graph.set_review_status(item, True)
    for src, dst in links:
        graph.set_link_status(src, dst, LinkStatus.LINKED)


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_score_all_reviewed(test_workspace: dict):
    # Review all items and links.
    items_to_review = ["EXP-1", "ASN-2", "TST-1", "TST-2", "TST-3"]
    links_to_review = [
        ("EXP-1", "ASN-2"),
        ("ASN-1", "TST-1"),
        ("ASN-1", "TST-2"),
        ("ASN-2", "DOC-1"),
        ("ASN-2", "TST-3"),
    ]
    review_graph_elements(test_workspace["graph"], items_to_review, links_to_review)
    expected_scores = {
        "EXP-1": (0.225, "Derived from supporting Statements"),
        "ASN-1": (0.4, "Derived from supporting Statements"),
        "ASN-2": (0.05, "Derived from supporting Statements"),
        "TST-1": (0.7, "SME with References"),
        "TST-2": (0.4, "SME with References"),
        # TST-3 is SME with no reference so is set to 0.
        "TST-3": (0.0, "Missing"),
        "DOC-1": (0.1, "SME with References"),
    }
    assert expected_scores == score.score(
        test_workspace["graph"], validator=Validator()
    )


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_score_unreviewed_items(test_workspace: dict):
    # Unreviewed items: ASN-2, TST-1
    items_to_review = ["EXP-1", "TST-2", "TST-3"]
    links_to_review = [
        ("EXP-1", "ASN-2"),
        ("ASN-1", "TST-1"),
        ("ASN-1", "TST-2"),
        ("ASN-2", "DOC-1"),
        ("ASN-2", "TST-3"),
    ]
    review_graph_elements(test_workspace["graph"], items_to_review, links_to_review)
    expected_scores = {
        "EXP-1": (0.08333, "Derived from supporting Statements"),
        "ASN-1": (0.16667, "Derived from supporting Statements"),
        "ASN-2": (0.0, "Missing"),
        "TST-1": (0.0, "Missing"),
        "TST-2": (0.4, "SME with References"),
        "TST-3": (0.0, "Missing"),
        "DOC-1": (0.1, "SME with References"),
    }
    assert expected_scores == score.score(
        test_workspace["graph"], validator=Validator()
    )


@pytest.mark.parametrize(
    "test_workspace",
    ["example_workspace"],
    indirect=True,
)
def test_score_suspect_links(test_workspace: dict):
    # Suspect links: (ASN-1 -> TST-1, EXP-1 -> ASN-2)
    items_to_review = ["EXP-1", "ASN-2", "TST-1", "TST-2", "TST-3"]
    links_to_review = [
        ("ASN-1", "TST-2"),
        ("ASN-2", "DOC-1"),
        ("ASN-2", "TST-3"),
    ]
    review_graph_elements(test_workspace["graph"], items_to_review, links_to_review)
    expected_scores = {
        "EXP-1": (0.08333, "Derived from supporting Statements"),
        "ASN-1": (0.16667, "Derived from supporting Statements"),
        "ASN-2": (0.05, "Derived from supporting Statements"),
        "TST-1": (0.7, "SME with References"),
        "TST-2": (0.4, "SME with References"),
        "TST-3": (0.0, "Missing"),
        "DOC-1": (0.1, "SME with References"),
    }
    assert expected_scores == score.score(
        test_workspace["graph"], validator=Validator()
    )
